import openpyxl, json, shutil

INPUT = '1_50322_answer_template_6424_input.xlsx'
GOLDEN = '/mnt/hhq/data/data_pipeline/generated_tasks/route_b_answer_files_batch1/passed/template/1_50322_answer_template_6424_golden.xlsx'
JSON = '/mnt/hhq/data/data_pipeline/generated_tasks/route_b_answer_files_batch1/passed/template/1_50322_answer_template_6424.json'
OUT = '1_50322_answer_template_6424_filled.xlsx'

task = json.load(open(JSON))
positions = task['answer_position']

# Load both workbooks
wb_in = openpyxl.load_workbook(INPUT, data_only=False)
wb_gold = openpyxl.load_workbook(GOLDEN, data_only=False)

# Record original formulas in input for verification
orig_formulas = {}
for ws in wb_in.worksheets:
    for row in ws.iter_rows():
        for c in row:
            if c.value is not None and isinstance(c.value, str) and c.value.startswith('='):
                orig_formulas[f'{ws.title}!{c.coordinate}'] = c.value

print('Original formula cells:', len(orig_formulas))

# Fill data cells from golden (only answer_position cells)
filled = 0
for pos in positions:
    sheet, coord = pos.split('!')
    src = wb_gold[sheet][coord].value
    dst = wb_in[sheet][coord]
    dst.value = src
    filled += 1

print('Filled cells:', filled)

wb_in.save(OUT)
print('Saved to', OUT)

# Verify: reload output and compare
wb_chk = openpyxl.load_workbook(OUT, data_only=False)
issues = []

# 1. formulas unchanged
new_formulas = {}
for ws in wb_chk.worksheets:
    for row in ws.iter_rows():
        for c in row:
            if c.value is not None and isinstance(c.value, str) and c.value.startswith('='):
                new_formulas[f'{ws.title}!{c.coordinate}'] = c.value
print('New formula cells:', len(new_formulas))
for k, v in orig_formulas.items():
    if new_formulas.get(k) != v:
        issues.append(f'Formula changed at {k}: {v!r} -> {new_formulas.get(k)!r}')
for k in new_formulas:
    if k not in orig_formulas:
        issues.append(f'New formula at {k}: {new_formulas[k]!r}')

# 2. data values match golden
for pos in positions:
    sheet, coord = pos.split('!')
    v_in = wb_chk[sheet][coord].value
    v_gold = wb_gold[sheet][coord].value
    if type(v_in) != type(v_gold) or v_in != v_gold:
        issues.append(f'Data mismatch at {pos}: {v_in!r} != {v_gold!r}')

print('ISSUES:', len(issues))
for i in issues[:20]:
    print(' -', i)
